public class TzhaarHPTrackerOverlay extends Overlay
{
	private final TzhaarHPTrackerPlugin plugin;
	private final TzhaarHPTrackerConfig config;
	private final Client client;
	private final ModelOutlineRenderer modelOutlineRenderer;
	private final NpcUtil npcUtil;

	private static final int ACTOR_OVERHEAD_TEXT_MARGIN = 40;
	private static final int ACTOR_HORIZONTAL_TEXT_MARGIN = 10;

	@Inject
	private TzhaarHPTrackerOverlay(TzhaarHPTrackerPlugin plugin, TzhaarHPTrackerConfig config, Client client,
								   ModelOutlineRenderer modelOutlineRenderer, NpcUtil npcUtil)
	{
		this.plugin = plugin;
		this.config = config;
		this.client = client;
		this.modelOutlineRenderer = modelOutlineRenderer;
		this.npcUtil = npcUtil;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_HIGHEST);
		setLayer(OverlayLayer.UNDER_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (plugin.isInAllowedCaves())
		{
			if (plugin.getFont() == null)
			{
				plugin.loadFont();
			}

			WorldView wv = client.getTopLevelWorldView();
			ArrayList<NPC> stackedNpcs = new ArrayList<>();

			for (PluginNPC n : plugin.getNpcs())
			{
				if (shouldHighlight(n.getNpc()))
				{
					NPCComposition npcComposition = n.getNpc().getTransformedComposition();
					if (npcComposition != null)
					{
						int size = npcComposition.getSize();

						//Only highlights NPCs - not pillars
						if (plugin.shouldShowHighlight(n) && n.getNpc().getId() != NpcID.INFERNO_INVISIBLE_3X3)
						{
							Color line = !n.isDead() ? config.highlightAliveColor() : config.highlightDeadColor();
							Color fill = !n.isDead() ? config.fillAliveColor() : config.fillDeadColor();

							if (config.dynamicColor() == TzhaarHPTrackerConfig.DynamicColor.BOTH || config.dynamicColor() == TzhaarHPTrackerConfig.DynamicColor.HIGHLIGHT)
							{
								line = plugin.getDynamicColor(n, true);
								fill = plugin.getDynamicColor(n, false);
							}

							if (config.highlightStyle().contains(TzhaarHPTrackerConfig.HighlightStyle.TILE))
							{
								LocalPoint lp = n.getNpc().getLocalLocation();
								if (lp != null)
								{
									Polygon tilePoly = Perspective.getCanvasTileAreaPoly(client, lp, size);
									if (tilePoly != null)
									{
										switch (config.tileLines())
										{
											case REG:
												renderPoly(graphics, line, fill, tilePoly, config.highlightThiCC());
												break;
											case DASH:
												renderPolygonDashed(graphics, line, fill, tilePoly, config.highlightThiCC(), size);
												break;
											case CORNER:
												renderPolygonCorners(graphics, line, fill, tilePoly, config.highlightThiCC());
												break;
										}
									}
								}
							}

							if (config.highlightStyle().contains(TzhaarHPTrackerConfig.HighlightStyle.TRUE_TILE))
							{
								LocalPoint lp = LocalPoint.fromWorld(wv, n.getNpc().getWorldLocation());
								if (lp != null)
								{
									lp = new LocalPoint(lp.getX() + size * 128 / 2 - 64, lp.getY() + size * 128 / 2 - 64, wv);
									Polygon tilePoly = Perspective.getCanvasTileAreaPoly(client, lp, size);
									if (tilePoly != null)
									{
										switch (config.tileLines())
										{
											case REG:
												renderPoly(graphics, line, fill, tilePoly, config.highlightThiCC());
												break;
											case DASH:
												renderPolygonDashed(graphics, line, fill, tilePoly, config.highlightThiCC(), size);
												break;
											case CORNER:
												renderPolygonCorners(graphics, line, fill, tilePoly, config.highlightThiCC());
												break;
										}
									}
								}
							}

							if (config.highlightStyle().contains(TzhaarHPTrackerConfig.HighlightStyle.SW_TILE))
							{
								LocalPoint lp = n.getNpc().getLocalLocation();
								if (lp != null)
								{
									int x = lp.getX() - (size - 1) * 128 / 2;
									int y = lp.getY() - (size - 1) * 128 / 2;
									Polygon tilePoly = Perspective.getCanvasTilePoly(client, new LocalPoint(x, y, wv));
									if (tilePoly != null)
									{
										switch (config.tileLines())
										{
											case REG:
												renderPoly(graphics, line, fill, tilePoly, config.highlightThiCC());
												break;
											case DASH:
												renderPolygonDashed(graphics, line, fill, tilePoly, config.highlightThiCC(), size);
												break;
											case CORNER:
												renderPolygonCorners(graphics, line, fill, tilePoly, config.highlightThiCC());
												break;
										}
									}
								}
							}

							if (config.highlightStyle().contains(TzhaarHPTrackerConfig.HighlightStyle.SW_TRUE_TILE))
							{
								LocalPoint lp = LocalPoint.fromWorld(wv, n.getNpc().getWorldLocation());
								if (lp != null)
								{
									Polygon tilePoly = Perspective.getCanvasTilePoly(client, lp);
									switch (config.tileLines())
									{
										case REG:
											renderPoly(graphics, line, fill, tilePoly, config.highlightThiCC());
											break;
										case DASH:
											renderPolygonDashed(graphics, line, fill, tilePoly, config.highlightThiCC(), size);
											break;
										case CORNER:
											renderPolygonCorners(graphics, line, fill, tilePoly, config.highlightThiCC());
											break;
									}
								}
							}
							if (config.highlightStyle().contains(TzhaarHPTrackerConfig.HighlightStyle.HULL))
							{
								Shape hull = n.getNpc().getConvexHull();
								if (hull != null)
								{
									renderPoly(graphics, line, fill, hull, config.highlightThiCC());
								}
							}
							if (config.highlightStyle().contains(TzhaarHPTrackerConfig.HighlightStyle.OUTLINE))
							{
								modelOutlineRenderer.drawOutline(n.getNpc(), (int) config.highlightThiCC(), line, 4);
							}
						}
						if ((config.showHp() != TzhaarHPTrackerConfig.HpLocation.OFF && n.getNpc().getId() != NpcID.INFERNO_INVISIBLE_3X3)
							|| (config.showPillarHp() != TzhaarHPTrackerConfig.HpLocation.OFF && n.getNpc().getId() == NpcID.INFERNO_INVISIBLE_3X3))
						{
							drawHp(graphics, stackedNpcs, n);
						}
					}
				}
			}

			if (config.showVenatorBounce())
			{
				drawVenatorArrows(graphics);
			}
		}
		return null;
	}

	private void renderPoly(Graphics2D g, Color outlineColor, Color fillColor, Shape polygon, double width)
	{
		if (polygon != null)
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, config.antiAlias() ? RenderingHints.VALUE_ANTIALIAS_ON : RenderingHints.VALUE_ANTIALIAS_OFF);
			g.setColor(outlineColor);
			g.setStroke(new BasicStroke((float) width));
			g.draw(polygon);
			g.setColor(fillColor);
			g.fill(polygon);
		}
	}

	/**
	 * Draws only the corners of NPC tile highlights - Made by Geheur
	 *
	 * @param graphics
	 * @param outlineColor
	 * @param fillColor
	 * @param poly
	 * @param width
	 */
	private void renderPolygonCorners(Graphics2D graphics, Color outlineColor, Color fillColor, Shape poly, double width)
	{
		if (poly instanceof Polygon)
		{
			Polygon p = (Polygon) poly;
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, config.antiAlias() ? RenderingHints.VALUE_ANTIALIAS_ON : RenderingHints.VALUE_ANTIALIAS_OFF);
			graphics.setColor(outlineColor);
			graphics.setStroke(new BasicStroke((float) width));

			int divisor = 7;
			for (int i = 0; i < p.npoints; i++)
			{
				int ptx = p.xpoints[i];
				int pty = p.ypoints[i];
				int prev = (i - 1) < 0 ? 3 : (i - 1);
				int next = (i + 1) > 3 ? 0 : (i + 1);
				int ptxN = ((p.xpoints[next]) - ptx) / divisor + ptx;
				int ptyN = ((p.ypoints[next]) - pty) / divisor + pty;
				int ptxP = ((p.xpoints[prev]) - ptx) / divisor + ptx;
				int ptyP = ((p.ypoints[prev]) - pty) / divisor + pty;
				graphics.drawLine(ptx, pty, ptxN, ptyN);
				graphics.drawLine(ptx, pty, ptxP, ptyP);
			}

			graphics.setColor(fillColor);
			graphics.fill(poly);
		}
	}

	/**
	 * Draws the corners and dashed lines along each side of NPC tile highlights - Made by Geheur
	 *
	 * @param graphics
	 * @param outlineColor
	 * @param fillColor
	 * @param poly
	 * @param width
	 * @param tiles
	 */
	private void renderPolygonDashed(Graphics2D graphics, Color outlineColor, Color fillColor, Shape poly, double width, int tiles)
	{
		if (poly instanceof Polygon)
		{
			Polygon p = (Polygon) poly;
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, config.antiAlias() ? RenderingHints.VALUE_ANTIALIAS_ON : RenderingHints.VALUE_ANTIALIAS_OFF);
			graphics.setColor(outlineColor);
			graphics.setStroke(new BasicStroke((float) width));

			int divisor = 7 * tiles;
			for (int i = 0; i < p.npoints; i++)
			{
				int ptx = p.xpoints[i];
				int pty = p.ypoints[i];
				int next = (i + 1) > 3 ? 0 : (i + 1);
				int ptxN = (p.xpoints[next]) - ptx;
				int ptyN = (p.ypoints[next]) - pty;
				float length = (float) Point2D.distance(ptx, pty, ptx + ptxN, pty + ptyN);
				float dashLength = length * 2f / divisor;
				float spaceLength = length * 5f / divisor;
				Stroke s = new BasicStroke((float) width, BasicStroke.CAP_SQUARE, BasicStroke.JOIN_MITER, 10, new float[]{dashLength, spaceLength}, dashLength / 2);
				graphics.setStroke(s);
				graphics.drawLine(ptx, pty, ptx + ptxN, pty + ptyN);
			}

			graphics.setColor(fillColor);
			graphics.fill(poly);
		}
	}

	private void drawHp(Graphics2D graphics, ArrayList<NPC> stackedNpcs, PluginNPC n)
	{
		if (n.getHp() <= 0)
		{
			return;
		}

		int offset = 0;
		NPC firstStack = null;
		for (NPC npc : stackedNpcs)
		{
			if (npc.getWorldLocation().getX() == n.getNpc().getWorldLocation().getX() && npc.getWorldLocation().getY() == n.getNpc().getWorldLocation().getY())
			{
				if (firstStack == null)
				{
					firstStack = npc;
				}
				offset += graphics.getFontMetrics().getHeight();
			}
		}

		final int zOffset;
		int npcOffset = firstStack != null ? firstStack.getLogicalHeight() : n.getNpc().getLogicalHeight();
		if (n.getNpc().getId() != NpcID.INFERNO_INVISIBLE_3X3)
		{
			switch (config.showHp())
			{
				case CENTER:
					zOffset = npcOffset / 2;
					break;
				case FEET:
					zOffset = 0;
					break;
				default:
					//Zuk is too tall for above HP bar to be seen by most players -> Set it to center if HP bar is selected
					zOffset = !Objects.equals(n.getNpc().getName(), "TzKal-Zuk") ? npcOffset + ACTOR_OVERHEAD_TEXT_MARGIN : npcOffset / 2;
			}
		}
		else
		{
			switch (config.showPillarHp())
			{
				case CENTER:
					zOffset = npcOffset / 2;
					break;
				case FEET:
					zOffset = 0;
					break;
				default:
					zOffset = npcOffset + ACTOR_OVERHEAD_TEXT_MARGIN;
			}
		}
		stackedNpcs.add(n.getNpc());
		String hp = Integer.toString(n.getHp());
		Point textLocation = offset > 0 ? firstStack.getCanvasTextLocation(graphics, hp, zOffset) : n.getNpc().getCanvasTextLocation(graphics, hp, zOffset);

		if (textLocation != null)
		{
			Point offsetLocation = new Point(textLocation.getX(), textLocation.getY() - offset);
			Color color = getHpColor(n);

			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, config.antiAlias() ? RenderingHints.VALUE_ANTIALIAS_ON : RenderingHints.VALUE_ANTIALIAS_OFF);
			Font oldFont = graphics.getFont();
			graphics.setFont(plugin.getFont());
			drawText(graphics, offsetLocation.getX(), offsetLocation.getY(), hp, color);
			graphics.setFont(oldFont);
		}
	}

	private Color getHpColor(PluginNPC npc)
	{
		Color color;
		switch (config.hpTextColorMode())
		{
			case SINGLE:
				color = config.hpTextColor();
				break;
			case ALIVE_DEAD:
				color = !npc.isDead() ? config.hpAliveTextColor() : config.hpDeadTextColor();
				break;
			default:
				if (config.dynamicColor() == TzhaarHPTrackerConfig.DynamicColor.BOTH || config.dynamicColor() == TzhaarHPTrackerConfig.DynamicColor.HP)
				{
					color = plugin.getDynamicColor(npc, true);
				}
				else
				{
					color = !npc.isDead() ? config.highlightAliveColor() : config.highlightDeadColor();
				}
		}

		if (config.hpFontAlpha() > 0)
		{
			return new Color(color.getRed(), color.getGreen(), color.getBlue(), config.hpFontAlpha());
		}
		return color;
	}

	public void drawText(Graphics2D graphics, int textX, int textY, String text, Color color)
	{
		if (!Strings.isNullOrEmpty(text))
		{
			graphics.setColor(Color.BLACK);
			drawTextBackground(graphics, new Point(textX, textY), text, color.getAlpha());

			graphics.setColor(color);
			graphics.drawString(text, textX, textY);
		}
	}

	private void drawTextBackground(Graphics2D graphics, Point textLoc, String text, int fontAlpha)
	{
		Color shadow = new Color(0, 0, 0, fontAlpha);
		switch (config.fontBackground())
		{
			case OUTLINE:
			{
				OverlayUtil.renderTextLocation(graphics, new Point(textLoc.getX(), textLoc.getY() + 1), text, shadow);
				OverlayUtil.renderTextLocation(graphics, new Point(textLoc.getX(), textLoc.getY() - 1), text, shadow);
				OverlayUtil.renderTextLocation(graphics, new Point(textLoc.getX() + 1, textLoc.getY()), text, shadow);
				OverlayUtil.renderTextLocation(graphics, new Point(textLoc.getX() - 1, textLoc.getY()), text, shadow);
				break;
			}
			case SHADOW:
			{
				OverlayUtil.renderTextLocation(graphics, new Point(textLoc.getX() + 1, textLoc.getY() + 1), text, shadow);
				break;
			}
			default:
				break;
		}
	}

	private boolean shouldHighlight(NPC n)
	{
		final NPCComposition c = n.getTransformedComposition();
		if (c != null && c.isFollower())
		{
			return false;
		}
		return plugin.getNpcs().stream().anyMatch(npc -> npc.getNpc().getIndex() == n.getIndex());
	}

	private void drawVenatorArrows(Graphics2D graphics)
	{
		List<Integer> bounces = plugin.getVenatorBounceOrder();
		if (bounces.size() < 2)
		{
			return;
		}

		Map<Integer, PluginNPC> npcMap = new HashMap<>();
		for (PluginNPC npc : plugin.getNpcs())
		{
			npcMap.put(npc.getNpc().getIndex(), npc);
		}

		for (int i = 0; i < bounces.size() - 1; ++i)
		{
			PluginNPC from = npcMap.get(bounces.get(i));
			PluginNPC to = npcMap.get(bounces.get(i + 1));
			if (from != null && to != null)
			{
				drawVenatorArrow(graphics, from, to, i);
			}
		}
	}

	private void drawVenatorArrow(Graphics2D graphics, PluginNPC from, PluginNPC to, int bounceIndex)
	{
		Polygon fp = from.getNpc().getCanvasTilePoly();
		Polygon tp = to.getNpc().getCanvasTilePoly();

		if (fp == null || tp == null)
		{
			return;
		}

		Point2D.Double fromCenter = getPolyMidpoint(fp);
		Point2D.Double toCenter = getPolyMidpoint(tp);
		double centerDistance = fromCenter.distance(toCenter);

		Graphics2D arrowGraphics = (Graphics2D) graphics.create();
		try
		{
			arrowGraphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			arrowGraphics.setColor(config.lineVenatorColor());
			arrowGraphics.setStroke(new BasicStroke(2.0f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));

			if (centerDistance < 2.0)
			{
				drawStackedVenatorArrow(arrowGraphics, fp, fromCenter, bounceIndex);
				return;
			}

			Point2D.Double start = getPolygonBoundaryPoint(fp, fromCenter, toCenter);
			Point2D.Double end = getPolygonBoundaryPoint(tp, toCenter, fromCenter);
			double dx = end.x - start.x;
			double dy = end.y - start.y;
			double length = Math.hypot(dx, dy);
			// Adjacent tile polygons share an edge, which makes both clipped points identical.
			// Pull the ends into the two polygons so the direction is still visible.
			if (length < 12.0)
			{
				start = interpolate(fromCenter, toCenter, 0.2);
				end = interpolate(fromCenter, toCenter, 0.8);
				dx = end.x - start.x;
				dy = end.y - start.y;
				length = Math.hypot(dx, dy);
			}

			double bend = Math.min(28.0, Math.max(8.0, length * 0.12));
			Point2D.Double control = new Point2D.Double(
				(start.x + end.x) / 2.0 - dy / length * bend,
				(start.y + end.y) / 2.0 + dx / length * bend);
			QuadCurve2D.Double curve = new QuadCurve2D.Double(
				start.x, start.y, control.x, control.y, end.x, end.y);
			arrowGraphics.draw(curve);
			drawArrowHead(arrowGraphics, control, end);
		}
		finally
		{
			arrowGraphics.dispose();
		}
	}

	private Point2D.Double getPolyMidpoint(Polygon polygon)
	{
		Rectangle2D bounds = polygon.getBounds2D();
		return new Point2D.Double((bounds.getMinX() + bounds.getMaxX()) / 2, (bounds.getMinY() + bounds.getMaxY()) / 2);
	}

	private void drawStackedVenatorArrow(Graphics2D graphics, Polygon polygon, Point2D.Double center, int bounceIndex)
	{
		Rectangle2D bounds = polygon.getBounds2D();
		double radiusX = Math.max(18.0, bounds.getWidth() * 0.55);
		double radiusY = Math.max(24.0, bounds.getHeight() * 1.1);
		boolean reverse = bounceIndex % 2 != 0;
		double verticalDirection = reverse ? 1.0 : -1.0;
		Point2D.Double start = new Point2D.Double(center.x + (reverse ? radiusX * 0.45 : -radiusX * 0.45), center.y);
		Point2D.Double end = new Point2D.Double(center.x + (reverse ? -radiusX * 0.45 : radiusX * 0.45), center.y);
		Point2D.Double control1 = new Point2D.Double(center.x + (reverse ? radiusX : -radiusX), center.y + verticalDirection * radiusY);
		Point2D.Double control2 = new Point2D.Double(center.x + (reverse ? -radiusX : radiusX), center.y + verticalDirection * radiusY);

		CubicCurve2D.Double curve = new CubicCurve2D.Double(
			start.x, start.y,
			control1.x, control1.y,
			control2.x, control2.y,
			end.x, end.y);
		graphics.draw(curve);
		drawArrowHead(graphics, control2, end);
	}

	private Point2D.Double getPolygonBoundaryPoint(Polygon polygon, Point2D.Double from, Point2D.Double toward)
	{
		double rayX = toward.x - from.x;
		double rayY = toward.y - from.y;
		double nearestT = Double.POSITIVE_INFINITY;

		for (int i = 0; i < polygon.npoints; ++i)
		{
			int next = (i + 1) % polygon.npoints;
			double edgeStartX = polygon.xpoints[i];
			double edgeStartY = polygon.ypoints[i];
			double edgeX = polygon.xpoints[next] - edgeStartX;
			double edgeY = polygon.ypoints[next] - edgeStartY;
			double denominator = cross(rayX, rayY, edgeX, edgeY);
			if (Math.abs(denominator) < 0.0001)
			{
				continue;
			}

			double offsetX = edgeStartX - from.x;
			double offsetY = edgeStartY - from.y;
			double t = cross(offsetX, offsetY, edgeX, edgeY) / denominator;
			double u = cross(offsetX, offsetY, rayX, rayY) / denominator;
			if (t > 0.0 && t <= 1.0 && u >= 0.0 && u <= 1.0 && t < nearestT)
			{
				nearestT = t;
			}
		}

		if (Double.isInfinite(nearestT))
		{
			return from;
		}
		return new Point2D.Double(from.x + rayX * nearestT, from.y + rayY * nearestT);
	}

	private double cross(double ax, double ay, double bx, double by)
	{
		return ax * by - ay * bx;
	}

	private Point2D.Double interpolate(Point2D.Double from, Point2D.Double to, double amount)
	{
		return new Point2D.Double(
			from.x + (to.x - from.x) * amount,
			from.y + (to.y - from.y) * amount);
	}

	private void drawArrowHead(Graphics2D graphics, Point2D.Double from, Point2D.Double tip)
	{
		Polygon arrowHead = new Polygon();
		arrowHead.addPoint(0, 0);
		arrowHead.addPoint(-7, -11);
		arrowHead.addPoint(7, -11);

		double angle = Math.atan2(tip.y - from.y, tip.x - from.x);
		AffineTransform transform = AffineTransform.getTranslateInstance(tip.x, tip.y);
		transform.rotate(angle - Math.PI / 2.0);
		graphics.fill(transform.createTransformedShape(arrowHead));
	}


